if (tsf > now) {
	data->tsf_offset += delta;
	if (bcn_int)
		data->bcn_delta = do_div(delta, bcn_int);
	else
		data->bcn_delta = 0;
} else {
	data->tsf_offset -= delta;
	if (bcn_int)
		data->bcn_delta = -(s64)do_div(delta, bcn_int);
	else
		data->bcn_delta = 0;
}

